// GitHub Pages 데모용 mock 데이터

// 월별 매출 데이터 (예: 라인차트, 바차트 등에서 사용)
export async function fetchMonthlySales(ym) {
  // ym은 무시하고 고정 데이터
  return [
    { ym: "2025-01", totalSales: 1230000 },
    { ym: "2025-02", totalSales: 1500000 },
    { ym: "2025-03", totalSales: 990000 },
    { ym: "2025-04", totalSales: 1710000 },
  ];
}

export async function fetchMonthlyRevenue(ym) {
  return fetchMonthlySales(ym);
}

// 특정 월 상위 품목 수량 Top N
export async function fetchItemQtyMonthlyByYm(ym) {
  return [
    { itemName: "데모 상품 A", qty: 120 },
    { itemName: "데모 상품 B", qty: 95 },
    { itemName: "데모 상품 C", qty: 60 },
    { itemName: "데모 상품 D", qty: 42 },
  ];
}

// 전월/전전월 등 비교나 누적용으로 쓰일 수 있는 전체 데이터
export async function fetchItemQtyMonthlyAll() {
  return [
    { ym: "2025-01", itemName: "데모 상품 A", qty: 120 },
    { ym: "2025-01", itemName: "데모 상품 B", qty: 80 },
    { ym: "2025-02", itemName: "데모 상품 A", qty: 140 },
    { ym: "2025-02", itemName: "데모 상품 B", qty: 90 },
    { ym: "2025-03", itemName: "데모 상품 A", qty: 160 },
    { ym: "2025-03", itemName: "데모 상품 B", qty: 88 },
  ];
}
